import{_ as a,o as r,c as t,a2 as n}from"./chunks/framework.CqGS6Fr9.js";const m=JSON.parse('{"title":"Procurement: orders, contracts and shared goals","description":"","frontmatter":{"pageId":"players/procurement","contentRevision":5},"headers":[],"relativePath":"en/players/procurement.md","filePath":"en/players/procurement.md"}'),o={name:"en/players/procurement.md"};function s(i,e,l,d,p,c){return r(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="procurement-orders-contracts-and-shared-goals" tabindex="-1">Procurement: orders, contracts and shared goals <a class="header-anchor" href="#procurement-orders-contracts-and-shared-goals" aria-label="Permalink to &quot;Procurement: orders, contracts and shared goals&quot;">​</a></h1><p>Applies to: Rimlink 0.9.2 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><p><strong>Buy order:</strong> specify a defName, quantity and unit price. The server reserves price × quantity; suppliers fulfill portions and are paid immediately.</p><p><strong>Directed contract:</strong> only the selected supplier sees the offer and must deliver the entire requested quantity at once.</p><p><strong>Shared goal:</strong> contributors&#39; resources remain in escrow until the goal is complete. The reward is then distributed proportionally; integer remainders go in ascending supplierId order, followed by the market fee. Cancellation returns resources to contributors and funds to the organizer.</p><p>Check the remaining quantity and deadline before confirming: an oversized delivery is not automatically split.</p><h2 id="procurement-steps" tabindex="-1">How do I create an order and supply resources? <a class="header-anchor" href="#procurement-steps" aria-label="Permalink to &quot;How do I create an order and supply resources? {#procurement-steps}&quot;">​</a></h2><p>Open the comms console → economy → <strong>Procurement</strong>. The organizer chooses a mode, technical defName (for example Steel), quantity, unit price/fund and deadline. Review the reserved amount and confirm; silver must already be in the wallet.</p><p>A supplier opens an available card, refreshes remaining quantity, selects beacon-area items and reviews the total. Buy orders accept partial remaining quantities; directed contracts require the entire amount from the named supplier. Over-quota delivery is rejected <strong>in full</strong>; the server does not split opaque blobs.</p><p>Accepted buy-order resources go to the organizer by mail; suppliers receive immediate payment less the market fee. Check net payout, contents and participation history. Refresh other public changes manually. An unknown response blocks new mutations until <strong>Retry request</strong> resolves the original intent.</p><h2 id="goal-example" tabindex="-1">Shared goals: when are rewards paid and how is rounding handled? <a class="header-anchor" href="#goal-example" aria-label="Permalink to &quot;Shared goals: when are rewards paid and how is rounding handled? {#goal-example}&quot;">​</a></h2><p>Example before fees: quota 3 Steel, fund 10; A supplies 1, B supplies 2. Integer shares are 3 and 6, leaving 1 silver. It goes to the lower supplier ID, producing 4/6 or 3/7. Market fees apply afterward. Until the quota is full, neither resources nor fund are released.</p><p>Cancellation/expiry of an incomplete goal returns resources to suppliers and the fund to the organizer. A partial contribution is not a free gift. Perishable storage may create supplier debt on normal settlement/cancellation; admin cancellation and reset/archive waive holding fees for those returns. Final delivery checks earlier suppliers&#39; freezes: do not “repair” a completed-looking card through manual grants.</p><p>Matching uses defName and quantity only. A promise of a particular quality/material is not enforced by this interface. Pawns and claims of NPC kills are not accepted.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>Only defName and quantity are matched: no quality, material, condition or pawn filters. Limits are 1,000,000 units, 720 hours, 1,000,000,000 silver and 100 deliveries; open orders are capped at min(20, MaxLotsPerPlayer). A previous supplier&#39;s freeze may prevent final goal settlement.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./economy">Wallet, mail and market</a></li><li><a href="./../admins/administration">Panel and moderation</a></li></ul>',19)])])}const h=a(o,[["render",s]]);export{m as __pageData,h as default};
